css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); border-radius: 50%; position: relative; overflow: hidden; background: radial-gradient(circle at 34% 30%, color-mix(in srgb, #fff 40%, var(--accent)), var(--accent) 68%, color-mix(in srgb, #000 45%, var(--accent))); box-shadow: inset calc(var(--loader-size) * -.12) calc(var(--loader-size) * -.12) calc(var(--loader-size) * .22) rgba(0, 0, 0, .45); }
.loader::before { content: ''; position: absolute; inset: 0; background: repeating-linear-gradient(90deg, transparent 0 11%, color-mix(in srgb, var(--accent-2) 55%, transparent) 11% 12.5%); animation: globe calc(var(--loader-speed) * 3) linear infinite; }
.loader::after { content: ''; position: absolute; inset: 8% 0; border-top: 2px solid color-mix(in srgb, var(--accent-2) 40%, transparent); border-bottom: 2px solid color-mix(in srgb, var(--accent-2) 40%, transparent); border-radius: 50%; }
@keyframes globe { to { background-position: calc(var(--loader-size) * .5) 0; } }
